def transform(grid):
    h, w = len(grid), len(grid[0])
    anchors = {r: row[0] for r, row in enumerate(grid) if row[0] != 0}
    period = next(p for p in range(1, h + 1)
                  if all(anchors[r] == anchors[s]
                         for r in anchors for s in anchors
                         if r % p == s % p))
    phases = {}
    for r, color in anchors.items():
        phases[r % period] = color
    # Fill unobserved phases with the nearest preceding known phase cyclically.
    known = set(phases)
    for phase in range(period):
        if phase not in phases:
            prior = min(known, key=lambda k: (phase - k) % period)
            phases[phase] = phases[prior]
    return [[phases[r % period]] * w for r in range(h)]

